/* Dev-only stand-in for the artifact `sample` capability, so the chat path can be tested locally.
 * Not published. A test agent plays Claude: it reads window.__mock.view(), calls page tools with
 * window.__mock.call(name, args), optionally streams text with stream(), then answers with finish(text).
 * Served by web/mock.html (generated by scripts/make_mock_page.py). */
const M = (window.__mock = { pending: null, history: [] });

// Separate saved state per tester: mock.html?ns=p3 keeps its own localStorage keys, so parallel test tabs
// on the same origin do not resume each other's work.
const NS = new URLSearchParams(location.search).get('ns');
if (NS) {
  const wrap = (fn) => function (k, ...rest) { return fn.call(this, `${NS}:${k}`, ...rest); };
  Storage.prototype.getItem = wrap(Storage.prototype.getItem);
  Storage.prototype.setItem = wrap(Storage.prototype.setItem);
  Storage.prototype.removeItem = wrap(Storage.prototype.removeItem);
}

function sample(input, opts = {}) {
  return new Promise((resolve, reject) => {
    M.pending = { input, opts, resolve, reject, calls: [], at: Date.now() };
    M.history.push({ kind: 'request', turns: input.length, tier: opts.modelTier || 'default' });
    if (opts.signal) opts.signal.addEventListener('abort', () => { if (M.pending && M.pending.opts === opts) { const text = M.pending.streamed || ''; M.pending = null; reject({ code: 'cancelled', text }); } });
  });
}
sample.limits = async () => ({ tools: true, images: false });
sample.json = async (input, opts) => JSON.parse((await sample(input, opts)).text);

M.view = () => {
  const p = M.pending;
  if (!p) return null;
  const turns = p.input.map((t) => ({ role: t.role, content: typeof t.content === 'string' ? t.content : JSON.stringify(t.content) }));
  return { tier: p.opts.modelTier || 'default', tools: (p.opts.tools || []).map((t) => ({ name: t.name, description: t.description, inputSchema: t.inputSchema })), turns, calls_so_far: p.calls };
};
M.call = async (name, args = {}) => {
  const p = M.pending;
  if (!p) throw new Error('no pending request');
  const t = (p.opts.tools || []).find((x) => x.name === name);
  if (!t) throw new Error(`no tool ${name}`);
  const out = await t.execute(args);
  p.calls.push({ name, args });
  M.history.push({ kind: 'tool', name, args });
  return out;
};
M.stream = (text) => { if (M.pending) M.pending.streamed = text; M.pending?.opts.onText?.({ text, delta: text }); };
M.finish = (text) => {
  const p = M.pending;
  if (!p) throw new Error('no pending request');
  M.pending = null;
  M.history.push({ kind: 'reply', text });
  p.resolve({ text, truncated: false, modelTierApplied: p.opts.modelTier || 'default' });
};
M.fail = (code) => { const p = M.pending; M.pending = null; p?.reject({ code, message: code }); };

window.claude = { use: async (name) => (name === 'sample' ? sample : null) };
